data.append((9,8,[(2,2,5,8),(3,7,8,2),(4,5,4,8),(6,4,8,2),(7,1,3,2),(9,3,6,5),(9,6,5,5),(9,8,0,8)]))
# brute linear output mod3 with input, r,c, area, height width, constant
sol=[]
for coeff in __import__('itertools').product(range(3),repeat=7):
 ok=True
 for h,w,cells in data:
  for r,c,i,o in cells:
   if (coeff[0]*r+coeff[1]*c+coeff[2]*i+coeff[3]*h+coeff[4]*w+coeff[5]*r*c+coeff[6])%3 != {2:0,5:1,8:2}[o]:ok=False;break
  if not ok:break
 if ok:sol.append(coeff)
print(sol[:10],len(sol))

# linear with k, r,c,i,h,w,flat,const
sol=[]
for co in itertools.product(range(3),repeat=8):
 ok=True
 for h,w,cells in data:
  for k,(r,c,i,o) in enumerate(cells):
   fs=[k,r,c,i,h,w,r*w+c,1]
   if sum(a*b for a,b in zip(co,fs))%3!={2:0,5:1,8:2}[o]:ok=False;break
  if not ok:break
 if ok:sol.append(co)
print(len(sol),sol[:5])

# output palette idx equal current, next, prev input mod3 or sums etc
for expr in ['cur','next','prev','cur+next','cur+prev','next+k','prev+k','cur+k','cur-k']:
 n=0
 for h,w,cells in data:
  for k,(r,c,i,o) in enumerate(cells):
   nxt=cells[(k+1)%len(cells)][2];prv=cells[(k-1)%len(cells)][2]
   v=eval(expr.replace('cur','i').replace('next','nxt').replace('prev','prv'))%3
   n+=v=={2:0,5:1,8:2}[o]
 print(expr,n)

# Allow arbitrary per-demo intercept for simple linear r,c,i,k,flat
for fsname,fsfun in [('r+c+i',lambda r,c,i,k,w:[r,c,i]),('k+i',lambda r,c,i,k,w:[k,i]),('flat+i',lambda r,c,i,k,w:[r*w+c,i]),('r*c+i',lambda r,c,i,k,w:[r*c,i]),('r+c',lambda r,c,i,k,w:[r,c]),('k',lambda r,c,i,k,w:[k]),('r*c',lambda r,c,i,k,w:[r*c])]:
 sols=[]
 for co in itertools.product(range(3),repeat=len(fsfun(1,1,1,0,1))):
  offsets=[];ok=True
  for h,w,cells in data:
   vals=[({2:0,5:1,8:2}[o]-sum(a*b for a,b in zip(co,fsfun(r,c,i,k,w))))%3 for k,(r,c,i,o) in enumerate(cells)]
   if len(set(vals))>1:ok=False;break
   offsets.append(vals[0])
  if ok:sols.append((co,offsets))
 print(fsname,sols[:3])

for h,w,cells in data:
 sol=[]
 for a,b,c in itertools.product(range(3),repeat=3):
  if all((a*k+b*i+c)%3=={2:0,5:1,8:2}[o] for k,(r,col,i,o) in enumerate(cells)):sol.append((a,b,c))
 print(h,w,sol)
